const body = $json.body || $json;
const operacao = typeof body.operacao === 'string' ? body.operacao.trim() : '';
const idEmpresa = typeof body.idEmpresa === 'string' ? body.idEmpresa.trim() : '';
const requestId = (typeof body.requestId === 'string' && body.requestId.trim().length > 0)
  ? body.requestId.trim()
  : ('sem-request-id-' + Date.now());
const dados = (body.dados && typeof body.dados === 'object') ? body.dados : {};

// Única operação reconhecida nesta Fase 1 — qualquer outra vira INVALID_OPERATION.
// Não criar branches vazios de Agenda/Financeiro/etc. aqui (ver sticky note desta
// workflow): adicionar a próxima operação exige voltar a este array E ao fluxo real.
const OPERACOES_SUPORTADAS = ['clientes.listar', 'servicos.listar'];

let erro_codigo = '';
let erro_mensagem = '';

if (!operacao) {
  erro_codigo = 'VALIDATION_ERROR';
  erro_mensagem = 'operacao é obrigatória.';
} else if (!idEmpresa) {
  erro_codigo = 'TENANT_REQUIRED';
  erro_mensagem = 'idEmpresa é obrigatório.';
} else if (!OPERACOES_SUPORTADAS.includes(operacao)) {
  erro_codigo = 'INVALID_OPERATION';
  erro_mensagem = 'Operação "' + operacao + '" não é reconhecida pelo APP-WF019.';
}

return [{ json: { operacao, idEmpresa, requestId, dados, erro_codigo, erro_mensagem } }];

// CLIENTES sozinha não tem "próximo atendimento" nem totais de atendimento/gasto
// (dependeriam de AGENDAMENTOS/PAGAMENTOS, fora do escopo desta Fase 1) — por isso o
// shape de integração devolvido aqui não inclui esses campos; o NestJS os preenche com
// um valor neutro documentado (ver clientes.service.ts, toClienteFromIntegracao).
// Nunca inclui ID_EMPRESA nem colunas técnicas do Sheets.
const requestId = $('CODE - Validar Envelope').first().json.requestId;
const linhas = $input.all().map((item) => item.json);

// alwaysOutputData garante um item mesmo quando a busca é 0 linhas legitimamente — esse
// placeholder não tem ID_CLIENTE, então é descartado aqui (não vira um cliente falso).
const clientes = linhas
  .filter((row) => row && row.ID_CLIENTE)
  .map((row) => ({
    idCliente: String(row.ID_CLIENTE),
    nome: row.NOME || '',
    telefone: row.TELEFONE || '',
    email: row.EMAIL || null,
    dataNascimento: row.DATA_NASCIMENTO || null,
    status: row.STATUS === 'INATIVO' ? 'INATIVO' : 'ATIVO',
    clienteDesde: row.DATA_CADASTRO ? String(row.DATA_CADASTRO).slice(0, 10) : null,
    ultimoAtendimento: row.ULTIMO_ATENDIMENTO ? String(row.ULTIMO_ATENDIMENTO).slice(0, 10) : null,
    observacoes: row.OBSERVACOES || null,
  }));

return [{ json: { clientes, requestId } }];

// SERVICOS: schema real confirmado (corrigido nesta tarefa) — ID_SERVICO, ID_EMPRESA,
// NOME, CATEGORIA, DESCRICAO, DURACAO_MIN, TEMPO_INTERVALO_MIN, VALOR, STATUS,
// DATA_CADASTRO, ULTIMA_ATUALIZACAO. DESCRICAO EXISTE na aba real (premissa anterior de
// que não existia estava errada) e agora é mapeada. CATEGORIA, TEMPO_INTERVALO_MIN,
// DATA_CADASTRO e ULTIMA_ATUALIZACAO existem na fonte mas NÃO fazem parte do contrato
// público `Servico` — deliberadamente nunca lidas/mapeadas aqui (decisão de escopo, não
// erro: adicioná-las ao contrato é decisão de produto fora desta tarefa). Nunca inclui
// ID_EMPRESA nem colunas técnicas do Sheets.
//
// Hardening (v1.3): ID_SERVICO, NOME, STATUS, DURACAO_MIN e VALOR são obrigatórios.
// STATUS só aceita exatamente 'ATIVO'/'INATIVO' (trim+uppercase, nunca outro valor vira
// 'ATIVO' por default — isso mascararia dado corrompido da fonte). Se QUALQUER serviço
// real da empresa tiver um desses campos inválido, a operação INTEIRA falha com
// UPSTREAM_ERROR — nunca devolve uma lista parcial silenciosamente incompleta.
//
// Hardening (v1.4): distingue o placeholder LEGÍTIMO do alwaysOutputData (item sem
// NENHUM campo operacional de serviço presente — busca realmente vazia) de uma linha
// real corrompida que tem algum campo preenchido mas ID_SERVICO vazio/ausente. O
// segundo caso NUNCA é tratado como "nenhum serviço" — é dado inválido, mesma falha de
// operação inteira das demais validações.
//
// Correção v1.5: DESCRICAO é mapeada (valor preenchido -> string normalizada/trim; vazio
// ou ausente -> null; nunca fabricada, nunca substituída pelo NOME). DESCRICAO é
// OPCIONAL — vazia/ausente nunca falha a operação (diferente de NOME/STATUS/
// DURACAO_MIN/VALOR) — mas conta como "campo operacional presente" na distinção
// placeholder x linha corrompida (v1.4), já que também é um dado real da linha.
const requestId = $('CODE - Validar Envelope').first().json.requestId;
const linhas = $input.all().map((item) => item.json);

const STATUS_VALIDOS = new Set(['ATIVO', 'INATIVO']);

function campoPresente(valor) {
  if (valor === undefined || valor === null) return false;
  if (typeof valor === 'string' && valor.trim() === '') return false;
  return true;
}

function normalizarValorMonetario(valor) {
  if (typeof valor === 'number') return valor;
  let texto = String(valor == null ? '' : valor).trim().replace(/^R\$\s*/i, '');
  if (texto.includes('.') && texto.includes(',')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  } else if (texto.includes(',')) {
    texto = texto.replace(',', '.');
  }
  return Number(texto);
}

let existeInvalido = false;
const servicos = [];

for (const row of linhas) {
  if (!row) continue;

  const temIdServico = campoPresente(row.ID_SERVICO);
  const temOutroCampo =
    campoPresente(row.NOME) ||
    campoPresente(row.STATUS) ||
    campoPresente(row.DURACAO_MIN) ||
    campoPresente(row.VALOR) ||
    campoPresente(row.DESCRICAO);

  if (!temIdServico && !temOutroCampo) {
    // Placeholder real do alwaysOutputData: busca legitimamente vazia — não é erro, não
    // é um serviço. Ignorado.
    continue;
  }

  if (!temIdServico) {
    // Linha real (tem algum campo operacional preenchido) mas sem ID_SERVICO — dado
    // corrompido da fonte, nunca "nenhum serviço".
    existeInvalido = true;
    continue;
  }

  const nome = typeof row.NOME === 'string' ? row.NOME.trim() : '';
  const status = typeof row.STATUS === 'string' ? row.STATUS.trim().toUpperCase() : '';
  const duracaoMinutos = Number(row.DURACAO_MIN);
  const valor = normalizarValorMonetario(row.VALOR);
  const descricaoBruta = typeof row.DESCRICAO === 'string' ? row.DESCRICAO.trim() : '';
  const descricao = descricaoBruta ? descricaoBruta : null;

  if (
    !nome ||
    !STATUS_VALIDOS.has(status) ||
    !Number.isFinite(duracaoMinutos) ||
    duracaoMinutos < 0 ||
    !Number.isFinite(valor) ||
    valor < 0
  ) {
    existeInvalido = true;
    continue;
  }

  servicos.push({ idServico: String(row.ID_SERVICO), nome, status, duracaoMinutos, valor, descricao });
}

if (existeInvalido) {
  // Mensagem genérica de propósito — nunca expõe qual linha/ID_SERVICO/ID_EMPRESA/
  // planilha está com o dado inválido.
  return [{ json: {
    erro_codigo: 'UPSTREAM_ERROR',
    erro_mensagem: 'Um ou mais serviços cadastrados possuem dados inválidos.',
    requestId,
  } }];
}

return [{ json: { servicos, requestId } }];

// Compartilhado entre clientes.listar e servicos.listar (branches mutuamente
// exclusivos por execução — só um dos dois IFs de erro técnico dispara) — mensagem
// genérica de propósito, não específica de uma fonte.
const requestId = $('CODE - Validar Envelope').first().json.requestId;
return [{ json: {
  erro_codigo: 'UPSTREAM_ERROR',
  erro_mensagem: 'Não foi possível consultar os dados no momento.',
  requestId,
} }];

// Compartilhado entre clientes.listar e servicos.listar (branches mutuamente
// exclusivos por execução — só um dos dois normalizadores roda) — lê qualquer um dos
// dois campos que o normalizador correspondente tiver produzido.
return [{ json: { ok: true, data: $json.clientes ?? $json.servicos ?? [], meta: { requestId: $json.requestId } } }];

// Alimentado por duas origens mutuamente exclusivas (envelope inválido OU falha técnica
// ao buscar CLIENTES) — ambas conectadas diretamente na mesma entrada deste node (não
// um Merge; ver sticky note desta workflow para o motivo). Nunca expõe stack, payload
// bruto do Sheets, credencial ou API key — só code/message já decididos antes.
return [{ json: {
  ok: false,
  error: { code: $json.erro_codigo, message: $json.erro_mensagem },
  meta: { requestId: $json.requestId },
} }];
